const response = $json.choices[0].message.content;
const { problem, mode } = $json.body;

const sections = {}
const currentSection = 'full';

response.split('\n').forEach(line => {
  const match = line.match(/^##\s+(.+)$/);
  if (match) {
    sections[match[1].trim().toLowerCase().replace(/\s+/g, '_')] = '';
    currentSection = match[1].trim().toLowerCase().replace(/\s+/g, '_');
  } else if (sections[currentSection] !== undefined) {
    sections[currentSection] += line + '\n';
  }
});

const wordCount = response.split(/\s+/).length;
const hasStructure = Object.keys(sections).length > 1;

return [{ json: {
  success: true,
  problem,
  mode,
  fullResponse: response,
  sections,
  wordCount,
  hasStructure,
  model: $json.model,
  usage: $json.usage,
  timestamp: new Date().toISOString()
} }];

const { fullResponse, problem, mode } = $json;

const critiquePrompt = `You are a rigorous critic. Evaluate this reasoning for:

Problem: ${problem}
Mode: ${mode}

Reasoning:
${fullResponse}

Check:
1. **Logical Validity** - Any fallacies, gaps, non-sequiturs?
2. **Evidence Quality** - Claims backed? Sources cited?
3. **Completeness** - Missing perspectives, edge cases?
4. **Bias Detection** - Confirmation bias, availability, anchoring?
5. **Calibration** - Confidence matched to evidence?
6. **Actionability** - Can this actually be executed?
7. **Falsifiability** - What would prove this wrong?

Provide specific criticisms with quotes. Score each dimension 1-10.
Then provide an improved version of the weakest section.`;

return [{ json: {
  systemPrompt: 'You are a hyper-critical thinking auditor. Be thorough and specific.',
  userPrompt: critiquePrompt,
  model: 'nvidia/nemotron-3-ultra-550b-a55b',
  temperature: 0.2,
  maxTokens: 4000
} }];

const { fullResponse, sections, critique, problem, mode, wordCount, hasStructure } = $json;

const markdown = `# Deep Thinking: ${problem.substring(0, 80)}...

**Mode:** ${mode}
**Generated:** ${new Date().toISOString()}
**Word Count:** ${wordCount}
**Structured:** ${hasStructure ? 'Yes' : 'No'}

---

## Reasoning

${fullResponse}

---

## Self-Critique

${critique}

---

## Key Sections

${Object.entries(sections).map(([k, v]) => `### ${k.replace(/_/g, ' ').toUpperCase()}\n${v.substring(0, 500)}${v.length > 500 ? '...' : ''}`).join('\n\n')}`;

return [{ json: { markdown, success: true } }];

const fs = require('fs');
const path = require('path');

const { markdown, problem } = $json;
const filename = `thinking-${problem.substring(0, 30).replace(/[^a-z0-9]/gi, '-')}-${Date.now()}.md`;
const savePath = path.join('/tmp/n8n-thinking', filename);

if (!fs.existsSync(path.dirname(savePath))) {
  fs.mkdirSync(path.dirname(savePath), { recursive: true });
}

fs.writeFileSync(savePath, markdown);

return [{ json: { success: true, filePath: savePath, filename } }];

const { problem, context, model } = $json.body;

const prompt = `Apply the "Six Thinking Hats" method to:

Problem: ${problem}
Context: ${context || 'None'}

## White Hat (Data & Facts)
- What do we know? What data exists? What's missing?

## Red Hat (Emotions & Intuition)
- Gut feelings, fears, hopes, aesthetic judgments

## Black Hat (Caution & Risks)
- What could go wrong? Weaknesses, dangers, why it might fail

## Yellow Hat (Optimism & Benefits)
- What could go right? Benefits, value, upside scenarios

## Green Hat (Creativity & Alternatives)
- New ideas, alternatives, lateral thinking, provocation

## Blue Hat (Process & Synthesis)
- Summary, next steps, decision framework, meta-reflection

Be thorough per hat. Then synthesize.

Output as structured sections.`;

return [{ json: {
  systemPrompt: 'You are a facilitator of structured parallel thinking.',
  userPrompt: prompt,
  model: model || 'nvidia/nemotron-3-ultra-550b-a55b',
  temperature: 0.3,
  maxTokens: 5000
} }];
